import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long inputNumber = Long.parseLong(br.readLine());
        System.out.println(computeOnes(inputNumber));
    }

    private static int countDigits(long number) {
        return (int) Math.log10(number) + 1;
    }

    private static long generateOnes(int length) {
        long result = 1;
        for (int i = 1; i < length; i++) {
            result = result * 10 + 1;
        }
        return result;
    }

    private static long computeOnes(long n) {
        if (n <= 6) return n;
        int digits = countDigits(n);
        long base = generateOnes(digits);
        long sum = base;
        int counter = 0;
        long diff = n;

        while (sum < n) {
            counter++;
            diff = n - sum;
            sum += generateOnes(digits);
        }

        long res;
        if (counter > 0)
            res = Math.min(counter * digits + computeOnes(diff),
                           (counter + 1) * digits + computeOnes(sum - n));
        else
            res = (counter + 1) * digits + computeOnes(sum - n);

        long nextBase = generateOnes(digits + 1);
        if (nextBase - n < n)
            res = Math.min(res, digits + 1 + computeOnes(nextBase - n));
        return res;
    }
}
